 "content": "def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    # The bars mark the two edges of an area; extend the sparse marker pattern
    # from the interior toward the corresponding edge(s), preserving marker cells as 4.
    vals={v for row in g for v in row}
    counts={v:sum(row.count(v) for row in g) for v in vals}
    bg=max(counts,key=counts.get)
    bar=max((v for v in vals if v!=bg),key=lambda v:counts[v])
    marks=[(r,c,g[r][c]) for r in range(h) for c in range(w) if g[r][c] not in (bg,bar)]
    if not marks:return g
    # Determine whether endpoint bars are horizontal or vertical.
    bars=[]
    for r in range(h):
        cs=[c for c in range(w) if g[r][c]==bar]
        if len(cs)>=2: bars.append(('h',r,min(cs),max(cs)))
    for c in range(w):
        rs=[r for r in range(h) if g[r][c]==bar]
        if len(rs)>=2: bars.append(('v',c,min(rs),max(rs)))
    # Two horizontal end bars: translate marker coordinates by bar offset and
    # extend both copies toward the nearest bar, filling only blank background.
    hb=[b for b in bars if b[0]=='h']
    if len(hb)>=2:
        first,last=hb[0],hb[-1]
        offset=first[2]-last[2]
        for r,c,col in marks:
            c2=c+offset
            if not 0<=c2<w: c2=c-offset
            for rr in range(1,r):
                if g[rr][c]==bg:g[rr][c]=col
            for rr in range(r+1,h-1):
                if g[rr][c2]==bg:g[rr][c2]=col
            g[r][c]=4
        return g
    # Two vertical end bars: fill the region between the bar columns with marker color.
    vb=[b for b in bars if b[0]=='v']
    if len(vb)>=2:
        left,right=vb[0],vb[-1]
        for r,c,col in marks:
            for cc in range(c+1,right[1]):
                if g[r][cc]==bg:g[r][cc]=col
            g[r][c]=4
        return g
    # Generic fallback: extend each marker to the opposite-side bar along its axis.
    for r,c,col in marks:
        for rr in range(h):
            if g[rr][c]==bg:g[rr][c]=col
        g[r][c]=4
    return g

